from common import *
import torch,sys,fcntl
from model import Model,feature_error
def main():
 lock=(P/'runs/gpu.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 assert not(E/'configs/training_frozen.json').exists()
 protocol={'created_utc':now(),'scope':'Unsupervised proposition-free skill-conditioned continuous pretraining, then frozen representations and few-label shared queries. Local existing CALVIN scene and unchanged scripted PhysicalOracle; not completion of the original HULC guide.','datasets':read(E/'results/data_audit.json'),'input':'Current dual-camera RGB DINO features and 15D robot proprioception. Fixed RGB hue components associate all three objects; this is an identity prior, not learned object discovery. No history, GT poses/depth/segmentation/contact, symbolic state, old semantic weights or their features.','representation':'Common AB-only per-channel normalization and 32D DINO channel PCA; preserve 2x2 ROI and 4x4 scene grids in both cameras. All objects retained. Four continuous 64D tokens (three objects, scene). Generic: AB-only fixed linear PCA; AE: new reconstruction encoder; interaction: same new encoder with action-conditioned prediction.','model':'Shared object MLP 268-128-64, scene MLP1039-256-64, shared contextual residual MLP192-128-64. Shared object transition uses own/scene/mean object token, skill type, target flag, posthold; scene transition uses scene/mean/target token. No hand-coded logical effects or preconditions.','action':'Whole open/lift/place/close primitive, one-hot skill type plus target object parameter when declared, plus historical endpoint posthold96/0 contract. First old unbound-place calls stay unbound.','loss':'Equal mean of object DINO, object RGB geometry, whole-scene DINO, robot error. Current reconstruction + successor reconstruction weighted coordinate-wise 1+4*min(abs(real_after-real_before),1) +0.25*stopgrad successor latent MSE +0.01 variance floor(.5). Every fourth update adds observed two/three-step chains at0.25 weight each. No task-relevance pruning.','seeds':[0,1],'batch':64,'lr':.0005,'stage1_updates':2000,'stage1_checkpoints':[500,1000,1500,2000],'stage1_selection':'C root-macro changed-weighted fixed-observation prediction MSE only. AE representation selected on C reconstruction then frozen before its own transition training. Generic and AE receive same2000 transition updates as joint model; AE additionally2000 reconstruction updates.','semantic':read(E/'configs/semantic_budget.json'),'stage2_updates':1200,'stage2_checkpoints':[300,600,900,1200],'stage2_selection':'C72 fixed state queries, equal Holding BCE/In BCE/drawer CE root mean; fixed0.5 binary thresholds, drawer argmax. No predicted-state label calibration. Full C reporting uses210 known development states, not independent test.','action_controls':'At evaluation, same latent plus deterministic shuffled full action (hold contract preserved), zero skill+target, and target permutation within skill family; compare normal executable calls separately from refused/failed. Copy-state baseline.','independent_D':'After model and evaluation code frozen, collect18 new roots:12 real four-skill chains (three colours x four starts: closed/open alternation), six challenge fixture roots (three colours x two layouts), nine paired reset conditions/root. Each root owns every branch/window. Old D never new blind. Main72 planned skills reported split into chain48 and challenge24; failures/refusals kept. Root-level provenance screened against old declarations.','closed_loop':'Predeclare seed0; six of the twelve new D chain roots (rep0/1 each colour), matched reset for all3arms. Model transitions supply all successors; shared query reads predicted latent. Enumerate eight parameterized skills, beam32 horizon4, goal min(In(target),Closed)>=0.8. Reobserve/replan each whole skill, max6 calls. No GT in search/stopping; physical evaluator scores afterwards. No-plan and false completion count.','error_policy':'Retain every run. At most one evidence-based correction, no D tuning. No formal success threshold is reduced. This is a bounded comparison, not a claim of solving the full original guide.'}
 save(E/'configs/protocol.json',protocol)
 # First128-transition training/leak smoke, no semantic input, fresh discarded model.
 rows=read(E/'data/public/states.json');pp=read(E/'data/public/pairs.json');ab=[p for p in pp if p['split']=='train'][:128];assert len({p['root_id']for p in ab})>1
 with np.load(E/'data/public/inputs.npz')as d:o=torch.tensor(d['objects'],device='cuda');s=torch.tensor(d['scene'],device='cuda')
 norm=dict(np.load(E/'data/public/normalization.npz'));torch.manual_seed(9876);m=Model(norm,'learned').cuda();opt=torch.optim.Adam(m.parameters(),lr=.0005);b=[p['before']for p in ab];n=[p['after']for p in ab];a=torch.tensor([p['action']for p in ab],device='cuda');losses=[]
 for _ in range(8):
  z=m.encode(o[b],s[b]);pred=m.transition(z,a);loss=feature_error(m.decode(pred),o[n],s[n],(o[b],s[b])).mean()+feature_error(m.decode(z),o[b],s[b]).mean();assert torch.isfinite(loss);opt.zero_grad();loss.backward();assert all(torch.isfinite(p.grad).all()for p in m.parameters()if p.grad is not None);opt.step();losses.append(float(loss))
 assert losses[-1]<losses[0];save(E/'results/first128_smoke.json',{'passed':True,'transitions':128,'roots':len({p['root_id']for p in ab}),'discarded_updates':8,'losses':losses,'labels_opened':0,'former_semantic_weights_loaded':0,'formal_initialization_unchanged':True,'split_disjoint':all(rows[i]['split']=='train'for i in b+n),'no_test':True})
 paths=list((E/'source').glob('*.py'))+[E/'configs/protocol.json',E/'configs/semantic_budget.json']+list((E/'data/public').glob('*.json'))+[E/'data/public/inputs.npz',E/'data/public/normalization.npz',DINO/'model.safetensors',P/'src/wm_symbolic/physical_oracle.py']
 save(E/'configs/training_frozen.json',{'created_utc':now(),'sha256':{str(p):sha(p)for p in paths}});print('FROZEN128PASS',losses,flush=True)
if __name__=='__main__':main()
